injectedCss.text:
/* C: is scale() the universal trigger? aurora keeps its drift as pure translate (confirmed in B);
   stl-pulse loses its scale and pulses on opacity alone. Nothing else changes. */
@keyframes aurora {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-3%, 2.5%, 0); }
}
@keyframes stl-pulse {
  0% { opacity: 0.9; }
  100% { opacity: 0; }
}
